-- =====================================================================
--  TREND EVENTS — MySQL database
--  Generated by database/build-sql.mjs from the website data (src/data.js,
--  src/servicePages.js) — texts and image paths match the frontend exactly.
--  MySQL 5.7+ / MariaDB 10.3+ · InnoDB · utf8mb4_unicode_ci · phpMyAdmin ready
--
--  Image columns hold either a site path ("/images/...") or a full URL.
-- =====================================================================

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

DROP TABLE IF EXISTS password_resets, event_build_services, event_builds, quote_requests, saved_venues, users,
  portfolio_images, portfolio_items, package_items, packages, venue_images, venue_category_map,
  venues, venue_categories, service_images, service_features, services, service_categories,
  event_type_features, event_types, guest_ranges, cities, site_settings;

-- 1. CITIES
CREATE TABLE cities (
  id         INT UNSIGNED NOT NULL AUTO_INCREMENT,
  name       VARCHAR(100) NOT NULL,
  slug       VARCHAR(120) NOT NULL,
  sort_order INT NOT NULL DEFAULT 0,
  is_active  TINYINT(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (id),
  UNIQUE KEY uq_cities_slug (slug)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- 2. GUEST RANGES ("Number of guests" dropdown; max NULL = no limit)
CREATE TABLE guest_ranges (
  id         INT UNSIGNED NOT NULL AUTO_INCREMENT,
  label      VARCHAR(50) NOT NULL,
  min_guests INT NOT NULL DEFAULT 0,
  max_guests INT NULL,
  sort_order INT NOT NULL DEFAULT 0,
  PRIMARY KEY (id),
  UNIQUE KEY uq_guest_ranges_label (label)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- 3. EVENT TYPES — name is plural (sections, Our Work filter), form_label is singular (dropdowns)
CREATE TABLE event_types (
  id            INT UNSIGNED NOT NULL AUTO_INCREMENT,
  slug          VARCHAR(120) NOT NULL,
  name          VARCHAR(150) NOT NULL,
  form_label    VARCHAR(150) NOT NULL,
  tagline       VARCHAR(255) NULL,
  description   TEXT NULL,
  min_guests    INT NULL,
  max_guests    INT NULL,
  image         VARCHAR(255) NULL,
  show_in_forms TINYINT(1) NOT NULL DEFAULT 1,
  sort_order    INT NOT NULL DEFAULT 0,
  is_active     TINYINT(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (id),
  UNIQUE KEY uq_event_types_slug (slug),
  KEY idx_event_types_forms (show_in_forms, sort_order)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE event_type_features (
  id            INT UNSIGNED NOT NULL AUTO_INCREMENT,
  event_type_id INT UNSIGNED NOT NULL,
  feature       VARCHAR(255) NOT NULL,
  sort_order    INT NOT NULL DEFAULT 0,
  PRIMARY KEY (id),
  KEY idx_etf_event_type (event_type_id, sort_order),
  CONSTRAINT fk_etf_event_type FOREIGN KEY (event_type_id) REFERENCES event_types (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;



-- 4. SERVICE CATEGORIES
CREATE TABLE service_categories (
  id         INT UNSIGNED NOT NULL AUTO_INCREMENT,
  slug       VARCHAR(120) NOT NULL,
  name       VARCHAR(150) NOT NULL,
  sort_order INT NOT NULL DEFAULT 0,
  PRIMARY KEY (id),
  UNIQUE KEY uq_service_categories_slug (slug)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- 5. SERVICES — slug = URL /services/<slug>; is_featured = the 10 Home cards (sort_order 1–10)
CREATE TABLE services (
  id                INT UNSIGNED NOT NULL AUTO_INCREMENT,
  category_id       INT UNSIGNED NOT NULL,
  slug              VARCHAR(120) NOT NULL,
  name              VARCHAR(150) NOT NULL,
  short_description VARCHAR(255) NULL,
  tagline           VARCHAR(255) NULL,
  long_description  TEXT NULL,
  image             VARCHAR(255) NULL,
  is_featured       TINYINT(1) NOT NULL DEFAULT 0,
  sort_order        INT NOT NULL DEFAULT 0,
  is_active         TINYINT(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (id),
  UNIQUE KEY uq_services_slug (slug),
  KEY idx_services_category (category_id),
  KEY idx_services_featured (is_featured, sort_order),
  CONSTRAINT fk_services_category FOREIGN KEY (category_id) REFERENCES service_categories (id) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE service_features (
  id         INT UNSIGNED NOT NULL AUTO_INCREMENT,
  service_id INT UNSIGNED NOT NULL,
  feature    VARCHAR(255) NOT NULL,
  sort_order INT NOT NULL DEFAULT 0,
  PRIMARY KEY (id),
  KEY idx_sf_service (service_id, sort_order),
  CONSTRAINT fk_sf_service FOREIGN KEY (service_id) REFERENCES services (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE service_images (
  id         INT UNSIGNED NOT NULL AUTO_INCREMENT,
  service_id INT UNSIGNED NOT NULL,
  image_path VARCHAR(255) NOT NULL,
  alt_text   VARCHAR(255) NULL,
  sort_order INT NOT NULL DEFAULT 0,
  PRIMARY KEY (id),
  KEY idx_si_service (service_id, sort_order),
  CONSTRAINT fk_si_service FOREIGN KEY (service_id) REFERENCES services (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


From venue visits and supplier contracts to seating plans and the running order on the day, one dedicated planner stays with you from start to finish — so you always know who to call.', '/images/services/event-planning.jpg', 1, 1),
(2, 1, 'event-coordination', 'Event Coordination', 'On-the-day management so you can relax', 'Relax — we run the day.', 'You have planned every detail; now you deserve to enjoy it. Our coordinators take over in the final weeks, confirm every supplier, build the running order and manage the event on the day — from the first delivery to the last guest leaving.

While you celebrate, we handle timings, suppliers, guests and any surprises quietly behind the scenes.', '/images/about-team.jpg', 0, 101),
(3, 1, 'event-concept-and-design', 'Event Concept & Design', 'A creative vision built around you', 'A creative vision built around you.', 'Every memorable event starts with a strong idea. Our designers turn your style, story and inspiration into a complete creative concept — colour palette, materials, florals, lighting and layout — presented in mood boards and 3D visuals.

Once you love the concept, we bring it to life with our décor, floral and production teams.', '/images/services/concept.jpg', 0, 102),
(4, 1, 'venue-finding', 'Venue Finding', 'The perfect space, sourced for you', 'The perfect space, sourced for you.', 'The venue sets the tone for everything else. Tell us your date, guest numbers, style and budget, and we will shortlist the best spaces — from grand ballrooms and rooftops to gardens, restaurants and unique hidden gems.

We arrange the viewings, negotiate the terms and check every technical detail, so you book with confidence.', 'https://images.unsplash.com/photo-1519167758481-83f550bb49b3?auto=format&fit=crop&w=1600&q=75', 0, 103),
(5, 1, 'event-styling', 'Event Styling', 'Every detail styled to your taste', 'Every detail styled to your taste.', 'Styling is where your event gets its personality. We choose and place every element — furniture, linens, tableware, candles, signage and décor accents — so the whole space feels cohesive, intentional and beautiful.

From lounge areas and welcome points to photo corners, every angle is styled to look perfect in person and in photographs.', '/images/services/styling.jpg', 0, 104),
(6, 2, 'catering', 'Catering', 'Exquisite menus for every occasion', 'Exquisite menus for every occasion.', 'Great food turns an event into an experience. Our chefs design menus around your taste, your guests and your theme — from elegant plated dinners and sharing feasts to canapés, food stations and late-night bites.

We take care of tastings, dietary requirements, service staff and the bar, so every course arrives on time and looks as good as it tastes.', '/images/services/catering.jpg', 1, 3),
(7, 2, 'decoration', 'Decoration', 'Bespoke styling & floral designs', 'Spaces transformed, down to the smallest detail.', 'Décor is what guests remember first. Our design team creates bespoke concepts — from romantic white florals and candlelight to bold, modern themes — and brings them to life with floral installations, backdrops, table styling and lighting.

Every piece is designed for your venue and your story. We handle the full build and the take-down, so the room looks perfect when the doors open.', '/images/event-engagement.jpg', 1, 2),
(8, 2, 'flowers', 'Flowers', 'Florals arranged by expert designers', 'Florals arranged by expert designers.', 'Flowers bring life, colour and fragrance to every celebration. Our florists design everything from bridal bouquets and buttonholes to tall centrepieces, floral arches and ceiling installations — using fresh, seasonal blooms.

We source the flowers, build the arrangements on site and make sure they look perfect from the first photo to the last dance.', '/images/services/flowers.jpg', 0, 107),
(9, 2, 'cakes-and-desserts', 'Cakes & Desserts', 'Showstopping cakes and dessert tables', 'Showstopping cakes and dessert tables.', 'A beautiful cake is often the centrepiece of the celebration. Our pastry partners create custom cakes in any style — classic tiered wedding cakes, modern sculpted designs and birthday showstoppers — that taste as good as they look.

Complete the experience with a styled dessert table full of macarons, mini desserts and sweet treats for your guests.', '/images/services/cakes.jpg', 0, 108),
(10, 2, 'table-styling', 'Table Styling', 'Tablescapes that set the mood', 'Tablescapes that set the mood.', 'Your guests spend most of the event at the table, so every detail matters. We design tablescapes with the perfect linens, chargers, cutlery, glassware, candles, florals and place cards to match your theme.

Whether you want romantic and soft, modern and minimal or bold and glamorous, every table is set by hand to perfection.', '/images/services/table.jpg', 0, 109),
(11, 3, 'photography', 'Photography', 'Capture every moment', 'Every moment, beautifully captured.', 'Your event lasts one day — the photographs last a lifetime. Our photographers work quietly in the background, capturing the natural moments, the details and the emotion, plus the portraits and group shots you will want to frame.

You receive a professionally edited gallery, ready to share, print and treasure.', '/images/services/photography.jpg', 1, 4),
(12, 3, 'videography', 'Videography', 'Cinematic event films', 'Cinematic films of your celebration.', 'Relive every speech, every dance and every smile. Our videographers film your event with cinema-grade cameras, gimbals and drones, then craft a film that tells the story of your day.

Choose a short highlight film for social media, a full-length documentary edit, or both.', '/images/services/videography.jpg', 1, 5),
(13, 3, 'dj-and-entertainment', 'DJ & Entertainment', 'Music and entertainment for every vibe', 'Music and energy for every vibe.', 'The right music keeps the dance floor full all night. Our DJs read the room and mix the perfect soundtrack — from elegant dinner playlists to peak-time party anthems — tailored to your requests.

Add live musicians, singers, dancers or performers to create moments your guests will never forget.', '/images/services/dj.jpg', 1, 6),
(14, 3, 'live-music', 'Live Music', 'Bands, singers and soloists', 'Bands, singers and soloists.', 'Nothing lifts the atmosphere like live music. We work with talented bands, singers, saxophonists, string quartets and pianists to create the soundtrack of your event — from the ceremony and drinks reception to a packed dance floor.

We help you choose the right artists, plan the set list and handle all the technical requirements.', '/images/services/live-music.jpg', 0, 113),
(15, 3, 'entertainment', 'Entertainment', 'Performers that wow your guests', 'Performers that wow your guests.', 'Give your guests moments they will talk about for years. From fire performers and dancers to magicians, acrobats, hosts and themed characters, we book entertainment that fits your event and your audience.

We coordinate timings, space and technical needs so every performance lands perfectly.', '/images/services/entertainment.jpg', 0, 114),
(16, 4, 'sound', 'Sound', 'Professional audio for any space', 'Professional audio for any space.', 'Clear sound is essential — for vows, speeches, presentations and music. Our audio team designs a sound system for your venue and guest numbers, so every word is heard and every song sounds great.

Experienced sound engineers run the system throughout the event, from the first sound check to the final track.', '/images/services/sound.jpg', 0, 115),
(17, 4, 'lighting', 'Lighting', 'Lighting design that transforms a room', 'Lighting design that transforms a room.', 'Lighting changes everything. Warm uplighting makes a room feel intimate, while moving heads and beams turn the dance floor into a show. Our lighting designers create the right mood for every moment of your event.

We plan, install and operate the full lighting rig, including programmed scenes for the entrance, first dance and party.', '/images/services/sound-lighting.jpg', 0, 116),
(18, 4, 'sound-and-lighting', 'Sound & Lighting', 'Professional audio and lighting production', 'Professional audio and lighting production.', 'Crystal-clear sound and beautiful lighting transform any space. Our technical team designs and runs the full audio and lighting setup for your event — from speeches and live music to atmospheric uplighting and dynamic show lighting.

We survey the venue in advance, bring professional equipment and stay on site to run everything on the night.', '/images/services/sound-lighting.jpg', 1, 7),
(19, 4, 'led-screens', 'LED Screens', 'Stunning visuals for bigger impact', 'Stunning visuals for bigger impact.', 'LED screens make your content impossible to miss. Whether it is a keynote presentation, a live camera feed, a brand reveal or a custom visual backdrop for the dance floor, we supply and operate high-resolution screens in any size.

Our team handles content playback, live switching and timing, so every visual appears exactly when it should.', '/images/services/led-screens.jpg', 1, 8),
(20, 4, 'stages', 'Stages', 'Decorated stages & backdrops', 'Beautifully decorated stages, designed around you.', 'The stage is the heart of the room — where the couple sits, the cake is cut and every photo is taken. We design and build decorated stages with floral backdrops, arches, draping, lighting and luxury seating, styled to match your theme.

From a romantic sweetheart stage for a wedding to an elegant backdrop for an engagement or a branded stage for a corporate event, everything is built and dressed by our décor team.', '/images/services/stage-decor.jpg', 1, 9),
(21, 4, 'special-effects', 'Special Effects', 'Create unforgettable moments', 'Create unforgettable moments.', 'Some moments deserve a little magic. Cold spark fountains for the first dance, confetti blasts at midnight, low fog for a dreamy entrance or CO2 jets for a product reveal — our special effects are designed to make your guests gasp.

All effects are indoor-safe where required and operated by trained technicians.', '/images/services/special-effects.jpg', 1, 10),
(22, 4, 'technical-production', 'Technical Production', 'End-to-end technical delivery', 'End-to-end technical delivery.', 'Large events need a technical team that brings everything together. We manage the full production — sound, lighting, LED screens, staging, power and rigging — as one coordinated project with a single point of contact.

From technical drawings and site surveys to show calling on the day, our production managers make sure everything runs safely and on cue.', '/images/services/led-screens-3.jpg', 0, 121);



-- 6. VENUE CATEGORIES
CREATE TABLE venue_categories (
  id         INT UNSIGNED NOT NULL AUTO_INCREMENT,
  slug       VARCHAR(120) NOT NULL,
  name       VARCHAR(150) NOT NULL,
  sort_order INT NOT NULL DEFAULT 0,
  PRIMARY KEY (id),
  UNIQUE KEY uq_venue_categories_slug (slug)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- 7. VENUES — slug = URL /venues/<slug>
CREATE TABLE venues (
  id          INT UNSIGNED NOT NULL AUTO_INCREMENT,
  slug        VARCHAR(120) NOT NULL,
  name        VARCHAR(150) NOT NULL,
  city_id     INT UNSIGNED NOT NULL,
  capacity    INT NOT NULL,
  price_from  DECIMAL(10,2) NOT NULL,
  currency    CHAR(3) NOT NULL DEFAULT 'GBP',
  description TEXT NULL,
  address     VARCHAR(255) NULL,
  is_featured TINYINT(1) NOT NULL DEFAULT 1,
  sort_order  INT NOT NULL DEFAULT 0,
  is_active   TINYINT(1) NOT NULL DEFAULT 1,
  created_at  TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at  TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_venues_slug (slug),
  KEY idx_venues_city (city_id),
  KEY idx_venues_capacity (capacity),
  CONSTRAINT fk_venues_city FOREIGN KEY (city_id) REFERENCES cities (id) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE venue_category_map (
  venue_id    INT UNSIGNED NOT NULL,
  category_id INT UNSIGNED NOT NULL,
  PRIMARY KEY (venue_id, category_id),
  KEY idx_vcm_category (category_id),
  CONSTRAINT fk_vcm_venue FOREIGN KEY (venue_id) REFERENCES venues (id) ON DELETE CASCADE,
  CONSTRAINT fk_vcm_category FOREIGN KEY (category_id) REFERENCES venue_categories (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE venue_images (
  id         INT UNSIGNED NOT NULL AUTO_INCREMENT,
  venue_id   INT UNSIGNED NOT NULL,
  image_path VARCHAR(255) NOT NULL,
  alt_text   VARCHAR(255) NULL,
  is_cover   TINYINT(1) NOT NULL DEFAULT 0,
  sort_order INT NOT NULL DEFAULT 0,
  PRIMARY KEY (id),
  KEY idx_vi_venue (venue_id, sort_order),
  CONSTRAINT fk_vi_venue FOREIGN KEY (venue_id) REFERENCES venues (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;




-- 8. PACKAGES — price_from NULL = tailored price (Custom Package → Build Your Event)
CREATE TABLE packages (
  id          INT UNSIGNED NOT NULL AUTO_INCREMENT,
  slug        VARCHAR(120) NOT NULL,
  name        VARCHAR(150) NOT NULL,
  description VARCHAR(500) NULL,
  price_from  DECIMAL(10,2) NULL,
  currency    CHAR(3) NOT NULL DEFAULT 'GBP',
  image       VARCHAR(255) NULL,
  is_popular  TINYINT(1) NOT NULL DEFAULT 0,
  sort_order  INT NOT NULL DEFAULT 0,
  is_active   TINYINT(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (id),
  UNIQUE KEY uq_packages_slug (slug)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE package_items (
  id         INT UNSIGNED NOT NULL AUTO_INCREMENT,
  package_id INT UNSIGNED NOT NULL,
  item       VARCHAR(255) NOT NULL,
  sort_order INT NOT NULL DEFAULT 0,
  PRIMARY KEY (id),
  KEY idx_pi_package (package_id, sort_order),
  CONSTRAINT fk_pi_package FOREIGN KEY (package_id) REFERENCES packages (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;



-- 9. PORTFOLIO (Our Work)
CREATE TABLE portfolio_items (
  id            INT UNSIGNED NOT NULL AUTO_INCREMENT,
  slug          VARCHAR(150) NOT NULL,
  title         VARCHAR(200) NOT NULL,
  event_type_id INT UNSIGNED NOT NULL,
  description   TEXT NULL,
  cover_image   VARCHAR(255) NULL,
  event_date    DATE NULL,
  sort_order    INT NOT NULL DEFAULT 0,
  is_active     TINYINT(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (id),
  UNIQUE KEY uq_portfolio_slug (slug),
  KEY idx_portfolio_event_type (event_type_id),
  CONSTRAINT fk_portfolio_event_type FOREIGN KEY (event_type_id) REFERENCES event_types (id) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE portfolio_images (
  id           INT UNSIGNED NOT NULL AUTO_INCREMENT,
  portfolio_id INT UNSIGNED NOT NULL,
  image_path   VARCHAR(255) NOT NULL,
  alt_text     VARCHAR(255) NULL,
  sort_order   INT NOT NULL DEFAULT 0,
  PRIMARY KEY (id),
  KEY idx_pimg_portfolio (portfolio_id, sort_order),
  CONSTRAINT fk_pimg_portfolio FOREIGN KEY (portfolio_id) REFERENCES portfolio_items (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;



-- 10. USERS (Account page) — passwords stored with PHP password_hash()
CREATE TABLE users (
  id            INT UNSIGNED NOT NULL AUTO_INCREMENT,
  full_name     VARCHAR(150) NOT NULL,
  email         VARCHAR(190) NOT NULL,
  phone         VARCHAR(30) NULL,
  password_hash VARCHAR(255) NOT NULL,
  role          ENUM('customer','admin') NOT NULL DEFAULT 'customer',
  is_active     TINYINT(1) NOT NULL DEFAULT 1,
  created_at    TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at    TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_users_email (email)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Password reset links (token stored as SHA-256 hash, valid 1 hour)
CREATE TABLE password_resets (
  id         INT UNSIGNED NOT NULL AUTO_INCREMENT,
  user_id    INT UNSIGNED NOT NULL,
  token_hash CHAR(64) NOT NULL,
  expires_at DATETIME NOT NULL,
  used_at    DATETIME NULL,
  ip_address VARCHAR(45) NULL,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_pr_token (token_hash),
  KEY idx_pr_user (user_id, created_at),
  CONSTRAINT fk_pr_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 11. SAVED VENUES (♡) — user_id for members, device_token for guests
CREATE TABLE saved_venues (
  id           INT UNSIGNED NOT NULL AUTO_INCREMENT,
  user_id      INT UNSIGNED NULL,
  device_token VARCHAR(64) NULL,
  venue_id     INT UNSIGNED NOT NULL,
  created_at   TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_saved_user_venue (user_id, venue_id),
  UNIQUE KEY uq_saved_device_venue (device_token, venue_id),
  KEY idx_saved_venue (venue_id),
  CONSTRAINT fk_saved_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE,
  CONSTRAINT fk_saved_venue FOREIGN KEY (venue_id) REFERENCES venues (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 12. QUOTE REQUESTS — Get a Quote, Check Availability, package/service quotes; source = page it came from
CREATE TABLE quote_requests (
  id             INT UNSIGNED NOT NULL AUTO_INCREMENT,
  user_id        INT UNSIGNED NULL,
  full_name      VARCHAR(150) NOT NULL,
  email          VARCHAR(190) NOT NULL,
  phone          VARCHAR(30) NULL,
  event_type_id  INT UNSIGNED NULL,
  event_date     DATE NULL,
  guest_range_id INT UNSIGNED NULL,
  city_id        INT UNSIGNED NULL,
  venue_id       INT UNSIGNED NULL,
  package_id     INT UNSIGNED NULL,
  service_id     INT UNSIGNED NULL,
  message        TEXT NULL,
  source         ENUM('quote_form','venue_page','package_page','service_page','build_page','homepage_search') NOT NULL DEFAULT 'quote_form',
  `status`       ENUM('new','contacted','quoted','won','lost') NOT NULL DEFAULT 'new',
  admin_notes    TEXT NULL,
  ip_address     VARCHAR(45) NULL,
  created_at     TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at     TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY idx_qr_status (`status`, created_at),
  KEY idx_qr_email (email),
  CONSTRAINT fk_qr_user       FOREIGN KEY (user_id)        REFERENCES users (id)        ON DELETE SET NULL,
  CONSTRAINT fk_qr_event_type FOREIGN KEY (event_type_id)  REFERENCES event_types (id)  ON DELETE SET NULL,
  CONSTRAINT fk_qr_guests     FOREIGN KEY (guest_range_id) REFERENCES guest_ranges (id) ON DELETE SET NULL,
  CONSTRAINT fk_qr_city       FOREIGN KEY (city_id)        REFERENCES cities (id)       ON DELETE SET NULL,
  CONSTRAINT fk_qr_venue      FOREIGN KEY (venue_id)       REFERENCES venues (id)       ON DELETE SET NULL,
  CONSTRAINT fk_qr_package    FOREIGN KEY (package_id)     REFERENCES packages (id)     ON DELETE SET NULL,
  CONSTRAINT fk_qr_service    FOREIGN KEY (service_id)     REFERENCES services (id)     ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 13. EVENT BUILDS (Build Your Event) — city NULL = Any, venue NULL = To be suggested
CREATE TABLE event_builds (
  id               INT UNSIGNED NOT NULL AUTO_INCREMENT,
  user_id          INT UNSIGNED NULL,
  quote_request_id INT UNSIGNED NULL,
  event_type_id    INT UNSIGNED NULL,
  city_id          INT UNSIGNED NULL,
  event_date       DATE NULL,
  guest_range_id   INT UNSIGNED NULL,
  venue_id         INT UNSIGNED NULL,
  `status`         ENUM('draft','submitted','proposal_sent','confirmed','cancelled') NOT NULL DEFAULT 'draft',
  created_at       TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at       TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY idx_eb_status (`status`),
  CONSTRAINT fk_eb_user   FOREIGN KEY (user_id)          REFERENCES users (id)          ON DELETE SET NULL,
  CONSTRAINT fk_eb_quote  FOREIGN KEY (quote_request_id) REFERENCES quote_requests (id) ON DELETE SET NULL,
  CONSTRAINT fk_eb_type   FOREIGN KEY (event_type_id)    REFERENCES event_types (id)    ON DELETE SET NULL,
  CONSTRAINT fk_eb_city   FOREIGN KEY (city_id)          REFERENCES cities (id)         ON DELETE SET NULL,
  CONSTRAINT fk_eb_guests FOREIGN KEY (guest_range_id)   REFERENCES guest_ranges (id)   ON DELETE SET NULL,
  CONSTRAINT fk_eb_venue  FOREIGN KEY (venue_id)         REFERENCES venues (id)         ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE event_build_services (
  event_build_id INT UNSIGNED NOT NULL,
  service_id     INT UNSIGNED NOT NULL,
  PRIMARY KEY (event_build_id, service_id),
  KEY idx_ebs_service (service_id),
  CONSTRAINT fk_ebs_build   FOREIGN KEY (event_build_id) REFERENCES event_builds (id) ON DELETE CASCADE,
  CONSTRAINT fk_ebs_service FOREIGN KEY (service_id)     REFERENCES services (id)     ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 14. SITE SETTINGS (contacts, footer, About stats)
CREATE TABLE site_settings (
  setting_key   VARCHAR(100) NOT NULL,
  setting_value TEXT NULL,
  PRIMARY KEY (setting_key)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


SET FOREIGN_KEY_CHECKS = 1;
