INSERT INTO event_types (id, slug, name, form_label, tagline, description, min_guests, max_guests, image, show_in_forms, sort_order) VALUES
(1, 'weddings', 'Weddings', 'Wedding', 'From intimate ceremonies to grand receptions, designed around your love story.', 'Your wedding day deserves a team that sweats every detail so you never have to. From the first venue visit to the last dance, we design a celebration that feels unmistakably yours — elegant florals, candlelit tablescapes, flawless timing and a guest experience people talk about for years.', 50, 500, '/images/event-wedding.jpg', 1, 1),
(2, 'birthdays', 'Birthdays', 'Birthday', 'Milestone birthdays and surprise parties styled to perfection.', 'Whether it is a first birthday, a sweet sixteen or a glamorous 50th, we turn your milestone into a party to remember. Choose a theme, a colour palette and a vibe — we bring it to life with styling, balloons, cakes and entertainment.', 20, 250, '/images/event-birthday.jpg', 1, 2),
(3, 'engagements', 'Engagements', 'Engagement', 'Proposals and engagement parties worth remembering forever.', 'From a secret proposal to an engagement party for all your loved ones, we create romantic moments with soft lighting, white florals and beautiful details. We handle the logistics quietly, so the only thing you need to focus on is the question — and the celebration afterwards.', 2, 200, '/images/engagment-1.avif', 1, 3),
(4, 'baby-showers', 'Baby Showers', 'Baby Shower', 'Soft, beautiful celebrations to welcome the newest arrival.', 'Celebrate the newest arrival with a soft, beautifully styled baby shower or gender reveal. We design pastel palettes, dreamy balloon arches and sweet treats, so the parents-to-be can simply relax and enjoy the day with family and friends.', 15, 100, '/images/event-baby-shower.jpg', 1, 4),
(5, 'private-parties', 'Private Parties', 'Private Party', 'Anniversaries, dinners and soirées hosted with effortless style.', 'Anniversaries, family dinners, cocktail evenings or just because — our private parties are hosted with effortless style. We find the right space, curate the menu and set the mood, so you can be a guest at your own party.', 10, 300, '/images/private-parties.avif', 1, 5),
(6, 'corporate-events', 'Corporate Events', 'Corporate Event', 'Company celebrations, team events and client evenings.', 'Team celebrations, client evenings, summer parties and company milestones — delivered on time, on budget and on brand. We work with your team to create events that strengthen relationships and reflect the quality of your business.', 30, 1000, 'https://images.unsplash.com/photo-1511578314322-379afb476865?auto=format&fit=crop&w=1600&q=75', 1, 6),
(7, 'conferences', 'Conferences', 'Conference', 'Seamless conferences with full technical production.', 'We plan conferences that run seamlessly from registration to the closing keynote. Our production team takes care of the stage, screens and sound, while our planners manage speakers, schedules and guests.', 50, 2000, '/images/conference.avif', 1, 7),
(8, 'product-launches', 'Product Launches', 'Product Launch', 'Launches that make an entrance and get people talking.', 'Make an entrance. We create launch events with dramatic reveals, immersive design and content-ready moments that get your product seen and shared — by press, partners and customers alike.', 50, 800, '/images/event-product-launch.jpg', 1, 8),
(9, 'award-nights', 'Award Nights', 'Award Night', 'Red-carpet evenings with staging, lighting and entertainment.', 'Red carpets, glittering stages and perfectly timed ceremonies. We produce award nights that honour achievement in style — from the welcome drinks to the final standing ovation.', 100, 1000, '/images/event-award-night.jpg', 0, 9),
(10, 'christmas-parties', 'Christmas Parties', 'Christmas Party', 'Festive parties for teams, families and friends.', 'Festive parties that bring teams, friends and families together. From elegant winter dinners to full-on themed parties, we take care of the décor, food, music and fun, so everyone can celebrate the season.', 20, 1000, '/images/event-christmas-party.jpg', 1, 10),
(11, 'brand-events', 'Brand Events', 'Brand Event', 'Immersive brand experiences that bring your story to life.', 'Pop-ups, activations and immersive brand experiences that bring your story to life. We combine creative design with smart production to create spaces people want to step into, photograph and remember.', NULL, NULL, '/images/event-brand-event.jpg', 0, 11),
(12, 'other', 'Other Event', 'Other Event', NULL, NULL, NULL, NULL, NULL, 1, 12);
