INSERT INTO venues (id, slug, name, city_id, capacity, price_from, currency, description, is_featured, sort_order) VALUES
(1, 'the-grand-hall', 'The Grand Hall', 1, 350, 2500, 'GBP', 'A timeless ballroom with crystal chandeliers, soaring ceilings and a sprung dance floor — made for grand weddings and gala dinners.', 1, 1),
(2, 'riverside-terrace', 'Riverside Terrace', 1, 200, 2000, 'GBP', 'An open-air terrace on the water with sunset views over the city skyline — perfect for summer receptions and cocktail parties.', 1, 2),
(3, 'the-crystal-room', 'The Crystal Room', 2, 400, 3000, 'GBP', 'Golden light, mirrored walls and a statement chandelier. The Crystal Room turns every celebration into an occasion.', 1, 3),
(4, 'skyline-view', 'Skyline View', 3, 250, 2200, 'GBP', 'A glass-walled rooftop space high above the city, ideal for launches, corporate evenings and after-dark parties.', 1, 4),
(5, 'the-garden-estate', 'The Garden Estate', 4, 300, 2800, 'GBP', 'Manicured lawns, rose gardens and a floral aisle — a romantic countryside setting just outside the city.', 1, 5),
(6, 'the-summit-centre', 'The Summit Centre', 1, 600, 3500, 'GBP', 'A flexible conference venue with built-in AV, breakout rooms and a 600-seat auditorium.', 1, 6),
(7, 'the-loft-kitchen', 'The Loft Kitchen', 5, 90, 1200, 'GBP', 'An industrial-chic restaurant with a private dining room — great for birthday dinners and intimate parties.', 1, 7),
(8, 'azure-bay-resort', 'Azure Bay Resort', 5, 220, 3200, 'GBP', 'A luxury resort hotel with poolside terraces and elegant suites for destination-style weddings and retreats.', 1, 8);
